import{_ as a,o as e,c as d,a5 as o}from"./chunks/framework.BEZBAInb.js";const b=JSON.parse('{"title":"アクター状態の切り替え","description":"","frontmatter":{"title":"アクター状態の切り替え","order":4},"headers":[],"relativePath":"ja/latest/tutorial/script/actor/actor-change-state.md","filePath":"ja/latest/tutorial/script/actor/actor-change-state.md","lastUpdated":1788455378000}'),r={name:"ja/latest/tutorial/script/actor/actor-change-state.md"};function i(n,t,s,c,l,h){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="アクター状態の切り替え" tabindex="-1">アクター状態の切り替え <a class="header-anchor" href="#アクター状態の切り替え" aria-label="Permalink to &quot;アクター状態の切り替え&quot;">​</a></h1><h2 id="機能説明" tabindex="-1">機能説明 <a class="header-anchor" href="#機能説明" aria-label="Permalink to &quot;機能説明&quot;">​</a></h2><p>指定したアクターの状態を切り替えます。安全な状態フレームを提供できるキャラクターは新旧の画面をブレンドし、それ以外はフェードアウト、状態適用、フェードインへ自動的にフォールバックします。トランジション完了後にストーリーを続行します。</p><h2 id="構文" tabindex="-1">構文 <a class="header-anchor" href="#構文" aria-label="Permalink to &quot;構文&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actor change &lt;キャラクター名&gt; &lt;新しい状態&gt;</span></span></code></pre></div><h2 id="パラメーター" tabindex="-1">パラメーター <a class="header-anchor" href="#パラメーター" aria-label="Permalink to &quot;パラメーター&quot;">​</a></h2><table tabindex="0"><thead><tr><th>パラメーター</th><th>必須</th><th>例</th><th>説明</th></tr></thead><tbody><tr><td>キャラクター</td><td>はい</td><td>kona</td><td>状態を切り替えるアクター名</td></tr><tr><td>新しい状態</td><td>はい</td><td>happy</td><td>切り替え先の新しい状態</td></tr></tbody></table><h2 id="例" tabindex="-1">例 <a class="header-anchor" href="#例" aria-label="Permalink to &quot;例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actor change kona happy</span></span></code></pre></div><h2 id="状態切り替えトランジション" tabindex="-1">状態切り替えトランジション <a class="header-anchor" href="#状態切り替えトランジション" aria-label="Permalink to &quot;状態切り替えトランジション&quot;">​</a></h2><p><code>actor change</code> はトランジション方式を自動的に選択します。</p><ol><li>現在と対象の状態フレームを提供できる場合は、プリマルチプライド Alpha シェーダーで画素をブレンドします。</li><li>安全な状態フレームを提供できない場合は、現在のアクターをフェードアウトし、状態を適用してフェードインします。</li><li>トランジションの完了後、次のストーリーコマンドを実行します。</li></ol><p><code>KonadoStageController</code> ノードのインスペクターでトランジションを設定できます。</p><table tabindex="0"><thead><tr><th>プロパティ</th><th>デフォルト</th><th>説明</th></tr></thead><tbody><tr><td><code>actor_state_transition_enabled</code></td><td><code>true</code></td><td>アクターの状態切り替えでフェードを有効にします</td></tr><tr><td><code>actor_state_transition_duration</code></td><td><code>0.3</code></td><td>トランジション全体の秒数です。安全なフォールバックではフェードアウトとフェードインで半分ずつ使用します</td></tr></tbody></table><p><code>actor_state_transition_enabled</code> を無効にするか、<code>actor_state_transition_duration</code> を <code>0</code> にすると、状態は即座に切り替わります。</p><p>トランジションはキャラクターシーンを複製しません。付属の AnimatedSprite2D サンプルは純粋なテクスチャ状態フレームで本当のブレンドを行います。独自の状態フレームは、一部の表示要素だけでなくキャラクター全体の画面を表す必要があります。動画、Spine、Live2D、安全で完全な状態フレームを提供できない独自シーンは自動的にフォールバックするため、スクリプト、音声、動的メディアが二重に実行されません。対象のアクターが存在しない場合や状態を適用できない場合でも、コマンドを完了してストーリーを続行します。</p>',16)])])}const u=a(r,[["render",i]]);export{b as __pageData,u as default};
